def _dq(self, w8: torch.Tensor, s: torch.Tensor, dtype: torch.dtype,
        storage: str = "e4m3fn") -> torch.Tensor:
    """Dequant stacked expert weights: w8 [E, O, I] fp8, s [E, O/128, I/128].

    ``storage="e4m3fnuz"`` (issue #71) reads the IN-PLACE converted
    stacks: fnuz bytes with DOUBLED scales. The fnuz-semantics cast
    recovers halved payloads; multiplying by the stored (doubled)
    scales reproduces the checkpoint values exactly."""
    e, o, i_ = w8.shape
    if storage == "e4m3fnuz":
        w = w8.view(torch.float8_e4m3fnuz).float()
    else:
        w = w8.float()
    w = w.view(e, o // 128, 128, i_ // 128, 128) * s.float()[:, :, None, :, None]
    return w.reshape(e, o, i_).to(dtype)

def _inplace_key(self):
    """(data_ptr, _version, device) of both expert stacks AND scales —
    the #69 invalidation pattern extended to every tensor the in-place
    fnuz conversion rewrites (issue #71)."""
    return (
        self.gate_up_proj.data_ptr(), self.gate_up_proj._version,
        self.gate_up_scale.data_ptr(), self.gate_up_scale._version,
        self.down_proj.data_ptr(), self.down_proj._version,
        self.down_scale.data_ptr(), self.down_scale._version,
        str(self.gate_up_proj.device),
    )

def _expert_storage(self) -> str:
    """"e4m3fnuz" iff the grouped path converted these weights in place
    (issue #71) and nothing has rewritten them since — the marker still
    matches. A checkpoint reload restores e4m3fn bytes and undoubled
    scales (bumping _version), which breaks the match: the FN decode
    paths run again until the next grouped forward reconverts."""
    key = getattr(self, "_fp8_inplace_key", None)
    if key is not None and key == self._inplace_key():
        return "e4m3fnuz"
    return "e4m3fn"

